mapper.update:
UPDATE fga_store
SET current_model_id = #{modelId},
    update_time = #{updateTime}
WHERE store_id = #{storeId}
  AND is_deleted = 0
  AND status = 0

UPDATE fga_store
SET current_zookie = current_zookie + 1,
    update_time = #{updateTime}
WHERE store_id = #{storeId}
  AND is_deleted = 0
  AND status = 0

mapper.select:
SELECT id, store_id, name, description, current_model_id, current_zookie, status, tenant_id, create_time, created_by, update_time, updated_by, is_deleted FROM fga_store WHERE is_deleted = 0
AND store_id < #{pageToken}
ORDER BY store_id DESC LIMIT #{pageSize}
